package com.billingcopilot.contract;
import com.billingcopilot.contract.ContractDtos.*; import com.billingcopilot.entity.*; import com.billingcopilot.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.io.IOException; import java.util.*;
@Service public class ContractService {
 private final ContractTextExtractor textExtractor; private final BillingRuleExtractor extractor; private final ContractDocumentRepository docs; private final ContractBillingRuleRepository rules;
 public ContractService(ContractTextExtractor t,BillingRuleExtractor e,ContractDocumentRepository d,ContractBillingRuleRepository r){textExtractor=t;extractor=e;docs=d;rules=r;}
 public ContractExtractionResult extract(MultipartFile file)throws IOException{return extractRaw(file);}
 @Transactional public SavedContract upload(long tenantId,MultipartFile file)throws IOException{var x=extractRaw(file); var doc=docs.save(new ContractDocument(tenantId,x.fileName())); List<ReviewableBillingRule> saved=new ArrayList<>(); for(var r:x.rules()){var e=rules.save(new ContractBillingRule(doc.getId(),r.service(),r.rate(),r.unit(),r.evidence().page(),r.evidence().quote(),r.confidence())); saved.add(dto(e));} return new SavedContract(doc.getId(),x.fileName(),saved,x.warnings());}
 @Transactional public ReviewableBillingRule review(long ruleId,String status){String s=status==null?"":status.trim().toUpperCase(Locale.ROOT); if(!Set.of("APPROVED","REJECTED","PENDING").contains(s)) throw new IllegalArgumentException("status must be APPROVED, REJECTED or PENDING"); var r=rules.findById(ruleId).orElseThrow(); r.review(s); return dto(rules.save(r));}
 public List<ReviewableBillingRule> list(long contractId){return rules.findByContractDocumentIdOrderById(contractId).stream().map(this::dto).toList();}
 private ContractExtractionResult extractRaw(MultipartFile file)throws IOException{if(file.isEmpty())throw new IllegalArgumentException("Contract file is empty"); if(file.getSize()>10_000_000)throw new IllegalArgumentException("Contract exceeds 10 MB MVP limit"); String n=file.getOriginalFilename()==null?"contract.pdf":file.getOriginalFilename(); if(!n.toLowerCase().endsWith(".pdf"))throw new IllegalArgumentException("PDF contracts only"); return extractor.extract(n,textExtractor.extract(file.getBytes()));}
 private ReviewableBillingRule dto(ContractBillingRule r){return new ReviewableBillingRule(r.getId(),r.getService(),r.getRate(),r.getUnit(),new SourceEvidence(r.getSourcePage()==null?1:r.getSourcePage(),r.getSourceQuote()),r.getConfidence()==null?0:r.getConfidence(),r.getReviewStatus());}
}
